mapper.update:
update process set

    ${moidfyFieldName}= #{modifyFieldValueArray[${index}]}

where id in

    #{id}

mapper.select:
select a.id,a.parent_id parentId, a.create_time createTime,a.update_time updateTime, a.entry_id entryId, a.field,a.field_name fieldName, a.term_text termText, a.state, a.readed, b.create_by creator,a.suggestion suggestion, (select suggestion from process where parent_id = a.id order by create_time desc limit 1) lastestCheck from process a left join process b on a.parent_id = b.id where a.type = 'term' and a.create_by = #{account}
and a.term_text like '%${keyword}%'
and
FIND_IN_SET(#{field}, a.field) != 0
and a.create_time >= #{beginTime}
and a.create_time < #{endTime}
and a.state in (${state})
and b.create_by in (${creator})
order by ${orderBy}, a.create_time desc
order by a.create_time desc

select a.id,a.parent_id parentId, a.create_time createTime,a.update_time updateTime, a.entry_id entryId, a.field,a.field_name fieldName, a.term_text termText, a.state, a.readed, a.create_by creator,a.suggestion suggestion, (select suggestion from process where parent_id = a.id order by create_time desc limit 1) lastestCheck from process a left join process b on a.parent_id = b.id where a.type = 'term' and a.parent_id in
#{processId}
order by a.create_time desc

select a.id,a.parent_id parentId, a.create_time createTime,a.update_time updateTime, a.entry_id entryId, a.comment_id commentId, a.comment_text commentText, a.place place, a.field,a.field_name fieldName, a.term_text termText, a.state, a.readed, a.create_by creator,a.suggestion suggestion, (select suggestion from process where parent_id = a.id order by create_time desc limit 1) lastestCheck from process a left join process b on a.parent_id = b.id where a.type = 'comment' and a.parent_id in
#{processId}
order by a.create_time desc

select DISTINCT b.create_by creator
from process a
left join process b on a.parent_id = b.id
where a.type = #{type}
and a.create_by = #{accountId}
